    window.__showcaseBootAt = performance.now();
    let bootFrameCount = 0;
    function countBootFrame() {
      if (document.body.dataset.viewerRuntimeActive === "true" || document.body.dataset.viewerTerminal === "true") return;
      bootFrameCount += 1;
      document.body.dataset.bootFrameCount = String(bootFrameCount);
      requestAnimationFrame(countBootFrame);
    }
    requestAnimationFrame(countBootFrame);
    window.__show600BootstrapFailure = function (message, source = "module-load-failed") {
      if (document.body.dataset.viewerTerminal === "true") return;
      const failure = document.querySelector("#error");
      document.body.classList.add("viewer-terminal-error");
      document.body.dataset.viewerTerminal = "true";
      document.body.dataset.viewerRuntimeActive = "false";
      document.body.dataset.machineSource = source;
      document.body.dataset.terminalFrameCount = document.body.dataset.bootFrameCount || "0";
      document.body.dataset.terminalFrameSource = "boot";
      document.body.dataset.runtimeErrorCount = "1";
      document.querySelector("#loader").hidden = true;
      document.querySelector("#error-copy").textContent = message;
      failure.hidden = false;
      for (const selector of ["#app", ".interface", "#inspector", "#machine-controls-body"]) document.querySelector(selector)?.setAttribute("inert", "");
      document.querySelector(".control-panel")?.setAttribute("aria-disabled", "true");
      document.querySelectorAll(".interface button, .interface input").forEach((control) => { control.disabled = true; });
      failure.focus({ preventScroll: true });
    };
    window.setTimeout(() => {
      if (document.body.dataset.viewerRuntimeActive === "true" || document.body.dataset.viewerTerminal === "true") return;
      window.__show600BootstrapFailure("The 600S rendering runtime did not initialize in time. Reload the page or verify the deployed vendor files.", "bootstrap-timeout");
    }, 8000);
